["n"] = 8,
},
[2503] = {
"Kyrakka and Erkhart Stormvein",
"Kyrakka and Erkhart roam the skies above the Ruby Life Pools coordinating attacks on the shrine below, while also taking out any interfering dragons. If left unchecked, they will burn the Life Pools to the ground and blow the remaining ash away in a cleansing elemental storm.",
2503,
25361,
"|cff66bbff|Hjournal:1:2503:8|h[Kyrakka and Erkhart Stormvein]|h|r",
1202,
2623,
2521,
["n"] = 8,
},
[2488] = {
"Melidrussa Chillworn",
"Melidrussa Chillworn leads the Primalist infusion efforts in the Ruby Life Pools. Her fervent belief is that she is protecting young dragon eggs from the influence of the titans and cleansing them from the stain of Order magic. She will stop at nothing to fulfill her calling and return the eggs to what she believes is their natural state.",
2488,
24995,
"|cff66bbff|Hjournal:1:2488:8|h[Melidrussa Chillworn]|h|r",
